const modale = document.querySelector("#ma-modale");
const declencheur = document.querySelector("#ouvrir-modale");
const focusables = () => modale.querySelectorAll("button, a, input, [tabindex]:not([tabindex='-1'])");
let elementPrecedent = null;

function ouvrir() {
  elementPrecedent = document.activeElement;
  modale.hidden = false;
  focusables()[0].focus();
  document.addEventListener("keydown", gererTouche);
}

function fermer() {
  modale.hidden = true;
  document.removeEventListener("keydown", gererTouche);
  elementPrecedent?.focus();
}

function gererTouche(event) {
  if (event.key === "Escape") fermer();
  if (event.key !== "Tab") return;
  const elements = focusables();
  const premier = elements[0];
  const dernier = elements[elements.length - 1];
  if (event.shiftKey && document.activeElement === premier) {
    event.preventDefault();
    dernier.focus();
  } else if (!event.shiftKey && document.activeElement === dernier) {
    event.preventDefault();
    premier.focus();
  }
}

declencheur.addEventListener("click", ouvrir);
modale.addEventListener("click", (event) => {
  if (event.target === modale) fermer();
});
modale.querySelector("[data-fermer]").addEventListener("click", fermer);

