const CLE_API = process.env.CLE_API;

function exigerToken(req, res, suite) {
  const enTete = req.get("Authorization") ?? "";
  const [type, token] = enTete.split(" ");

  if (type !== "Bearer" || !token || token.length < 8) {
    return res.status(401).json({ erreur: "Token manquant ou invalide." });
  }
  if (token !== CLE_API) {
    return res.status(401).json({ erreur: "Token refusé." });
  }

  suite();
}

module.exports = { exigerToken };

