function grouperPar<T, C extends string | number>(
  elements: T[], cle: (element: T) => C): Record<C, T[]> {
  return elements.reduce((acc, element) => {
    const k = cle(element);
    (acc[k] ??= []).push(element);
    return acc;
  }, {} as Record<C, T[]>);
}

