class Limiteur {
  #comptes = new Map<string, number>();

  autoriser(cle: string, max: number): boolean {
    const compteur = (this.#comptes.get(cle) ?? 0) + 1;
    this.#comptes.set(cle, compteur);
    return compteur <= max;
  }

  reinitialiser(cle: string): void {
    this.#comptes.delete(cle);
  }
}

