def moyenne_mobile(valeurs: list[float], fenetre: int) -> list[float]:
    resultats = []
    for i in range(len(valeurs) - fenetre + 1):
        resultats.append(round(sum(valeurs[i:i + fenetre]) / fenetre, 2))
    return resultats


