def cesar(texte: str, decalage: int) -> str:
    resultat = []
    for c in texte:
        if c.isalpha() and c.isascii():
            base = ord("a") if c.islower() else ord("A")
            resultat.append(chr((ord(c) - base + decalage) % 26 + base))
        else:
            resultat.append(c)
    return "".join(resultat)


print(cesar("abc", 1))  # bcd

