from pathlib import Path
from PIL import Image


def inventaire_images(dossier: Path) -> list[str]:
    lignes = []
    for chemin in sorted(dossier.glob("*.png")):
        with Image.open(chemin) as image:
            lignes.append(f"{chemin.name} : {image.width}x{image.height}")
    return lignes


for ligne in inventaire_images(Path("images")):
