def variables_requises(*noms: str) -> dict[str, str]:
    manquantes = [n for n in noms if not os.environ.get(n)]
    if manquantes:
        raise SystemExit(f"Variables manquantes : {', '.join(manquantes)}")
    return {n: os.environ[n] for n in noms}


